`timescale 1ns/1ns
module top;
logic data,control;wire a,q0,q1;
notif0 g(a,data,control);nmos m0(q0,a,1'b1);nmos m1(q1,a,1'b1);
assign (weak1,weak0) q0=1'b0;assign (weak1,weak0) q1=1'b1;
initial begin data=1;control=1;#1;$display("%b %b %b",a,q0,q1);
control=1'bx;#1;$display("%b %b %b",a,q0,q1);
data=1'bx;control=0;#1;$display("%b %b %b",a,q0,q1);end
endmodule
